#!/usr/bin/env bash
# Adds a default-deny egress firewall to a setup generated by init-dockerclaude.sh.
# Run from the project root. Pass --defaults to skip prompts. Re-running init-dockerclaude.sh removes the firewall again.

set -euo pipefail

OUT_DIR=".dockerclaude"
SCRIPT_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
FIREWALL_PACKAGES="iptables ip6tables ipset bind-tools jq su-exec"

ask() {
  local reply
  read -r -p "$1 [$2]: " reply || true
  printf '%s' "${reply:-$2}"
}

require_generated_setup() {
  local file
  for file in Dockerfile compose.yml entrypoint.sh; do
    [ -f "$OUT_DIR/$file" ] || { echo "$OUT_DIR/$file not found. Run init-dockerclaude.sh first."; exit 1; }
  done
  if grep -q init-firewall.sh "$OUT_DIR/Dockerfile"; then
    echo "Firewall already added. Edit $OUT_DIR/allowed-domains.txt to change the allowlist."
    exit 0
  fi
}

collect_domains() {
  local domains=() extra line
  while IFS= read -r line; do domains+=("$line"); done < <(
    sed -e 's/#.*//' -e 's/[[:space:]]//g' -e '/^$/d' "$SCRIPT_DIR/config/base-domains.txt")
  grep -q corepack "$OUT_DIR/Dockerfile" && domains+=(repo.yarnpkg.com)
  grep -q python3 "$OUT_DIR/Dockerfile" && domains+=(pypi.org files.pythonhosted.org)
  extra="-"
  [ "${1:-}" = --defaults ] || extra=$(ask "Extra allowed domains besides Anthropic, npm and GitHub (space separated, '-' for none)" "-")
  # shellcheck disable=SC2206
  [ "$extra" != "-" ] && domains+=($extra)
  printf '%s\n' "${domains[@]}"
}

write_allowed_domains() {
  local file="$OUT_DIR/allowed-domains.txt"
  if [ -f "$file" ]; then
    echo "Keeping existing $file"
    return
  fi
  {
    printf '# One domain per line. @github adds GitHub web/api/git ranges.\n'
    printf '# Read at container start; restart the container after editing.\n'
    collect_domains "$@"
  } >"$file"
}

write_firewall() {
  cat >"$OUT_DIR/init-firewall.sh" <<'EOF'
#!/bin/bash
# Default-deny egress, modeled on the claude-code reference dev container.
set -euo pipefail

DOMAINS_FILE=/workspace/.dockerclaude/allowed-domains.txt
IPV4_RE='^[0-9]{1,3}(\.[0-9]{1,3}){3}(/[0-9]{1,2})?$'

add_ip() {
  [[ "$1" =~ $IPV4_RE ]] && ipset add allowed "$1" -exist
  return 0
}

ipset create allowed hash:net -exist
ipset flush allowed

while IFS= read -r line || [ -n "$line" ]; do
  entry=${line%%#*}
  entry=${entry//[[:space:]]/}
  [ -n "$entry" ] || continue
  if [ "$entry" = "@github" ]; then
    while read -r cidr; do add_ip "$cidr"; done < <(curl -fsS --connect-timeout 10 https://api.github.com/meta |
      jq -r '(.web + .api + .git)[]')
    continue
  fi
  ips=$(dig +short A "$entry" | grep -E "$IPV4_RE" || true)
  [ -n "$ips" ] || echo "Warning: could not resolve $entry"
  for ip in $ips; do add_ip "$ip"; done
done <"$DOMAINS_FILE"

iptables -F
iptables -A INPUT -i lo -j ACCEPT
iptables -A OUTPUT -o lo -j ACCEPT
iptables -A INPUT -m conntrack --ctstate ESTABLISHED,RELATED -j ACCEPT
iptables -A OUTPUT -m conntrack --ctstate ESTABLISHED,RELATED -j ACCEPT
iptables -A OUTPUT -m set --match-set allowed dst -j ACCEPT
iptables -A OUTPUT -j REJECT --reject-with icmp-admin-prohibited
iptables -P INPUT DROP
iptables -P FORWARD DROP
iptables -P OUTPUT DROP

ip6tables -F 2>/dev/null || true
ip6tables -A INPUT -i lo -j ACCEPT 2>/dev/null || true
ip6tables -A OUTPUT -o lo -j ACCEPT 2>/dev/null || true
for chain in INPUT FORWARD OUTPUT; do ip6tables -P "$chain" DROP 2>/dev/null || true; done

if curl -fsS --connect-timeout 5 -o /dev/null https://example.com 2>/dev/null; then
  echo "Firewall check failed: example.com is reachable"
  exit 1
fi
if ! curl -sS --connect-timeout 10 -o /dev/null https://api.anthropic.com; then
  echo "Firewall check failed: api.anthropic.com is unreachable"
  exit 1
fi
echo "Firewall active. Allowlist: .dockerclaude/allowed-domains.txt"
EOF
  chmod 755 "$OUT_DIR/init-firewall.sh"
}

patch_dockerfile() {
  local file="$OUT_DIR/Dockerfile"
  sed -i.bak \
    -e "/^RUN apk add --no-cache /s/\$/ $FIREWALL_PACKAGES/" \
    -e 's|^COPY entrypoint.sh /usr/local/bin/$|COPY init-firewall.sh entrypoint.sh /usr/local/bin/|' \
    -e '/^USER node$/d' "$file"
  rm -f "$file.bak"
  printf 'CMD ["claude"]\n' >>"$file"
}

patch_entrypoint() {
  local file="$OUT_DIR/entrypoint.sh"
  sed -i.bak 's|^exec claude "\$@"$|/usr/local/bin/init-firewall.sh\nexec su-exec node "$@"|' "$file"
  rm -f "$file.bak"
}

patch_compose() {
  local file="$OUT_DIR/compose.yml"
  sed -i.bak '/^    cap_drop:$/{n;a\
    cap_add:\
      - NET_ADMIN\
      - NET_RAW\
      - SETUID\
      - SETGID
}' "$file"
  rm -f "$file.bak"
}

main() {
  require_generated_setup
  write_allowed_domains "$@"
  write_firewall
  patch_dockerfile
  patch_entrypoint
  patch_compose
  echo "Firewall added. Allowlist: $OUT_DIR/allowed-domains.txt"
  echo "Rebuild: docker compose -f $OUT_DIR/compose.yml build"
}

main "$@"
